function initRotatingText(){document.querySelectorAll(".rotating-text-wrapper").forEach(t=>{t.dataset.intervalId&&clearInterval(parseInt(t.dataset.intervalId,10));const e=t.getAttribute("data-words");if(!e)return;const n=e.split(",").map(t=>t.trim());if(0===n.length)return;let r=0;t.innerHTML=`<span class="rotating-text">${n[0]}</span>`;const i=setInterval(()=>{const e=t.querySelector(".rotating-text");e&&(e.style.animation="slideOutFade 0.5s ease-in forwards"),setTimeout(()=>{t.querySelector(".rotating-text")&&(r=(r+1)%n.length,t.innerHTML=`<span class="rotating-text">${n[r]}</span>`)},500)},3500);t.dataset.intervalId=i.toString()})}function initScrollEffects(){const t=document.querySelectorAll(".fade-in-section, .story-step"),e=document.querySelectorAll(".nav-link"),n=document.querySelectorAll(".scroll-section"),r=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(t.target.classList.add("is-visible"),r.unobserve(t.target))})},{threshold:.15});t.forEach(t=>{r.observe(t)});const i=new IntersectionObserver(t=>{t.forEach(t=>{if(t.isIntersecting){const n=t.target.getAttribute("id");e.forEach(t=>{t.getAttribute("href")===`#${n}`?t.classList.add("active"):t.classList.remove("active")})}})},{threshold:.4});n.forEach(t=>{i.observe(t)})}"undefined"!=typeof window&&(window.initRotatingText=initRotatingText,window.initScrollEffects=initScrollEffects);